var i=`0389-judd-mat-gaardebounen`;var t=`world-0389`;var a=`LU`;var o=`western-europe`;var s=4;var r=99;var m={en:`Judd mat Gaardebounen`,ua:`Копчена свинина з бобами`};var d={en:`A traditional Luxembourg dish made with smoked pork loin, yellow onion, bay leaf, broad beans (fresh). This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Люксембург. Основні інгредієнти: копчена свиняча корейка, жовта цибуля, лавровий лист, свіжі кінські боби. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 75 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 75 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:75,i:[[`smoked-pork-loin`,780,`g`],[`water`,1400,`ml`],[`yellow-onion`,140,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 22 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 22 хвилин до м’якості та готовності.`,t:[`simmering`],m:22,i:[[`broad-beans-fresh`,350,`g`],[`carrot`,150,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,20,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:i,id:t,country:`LU`,region:o,servings:4,minutes:99,title:m,text:d,steps:l};export{a as country,g as default,t as id,r as minutes,o as region,s as servings,i as slug,l as steps,d as text,m as title};